void TRTBEVDetNode::callback(
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_fl_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_f_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_fr_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_bl_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_b_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_br_img)
{
  std::vector<cv::Mat> imgs;

  imgs.emplace_back(cloneAndResize(msg_fl_img));
  imgs.emplace_back(cloneAndResize(msg_f_img));
  imgs.emplace_back(cloneAndResize(msg_fr_img));
  imgs.emplace_back(cloneAndResize(msg_bl_img));
  imgs.emplace_back(cloneAndResize(msg_b_img));
  imgs.emplace_back(cloneAndResize(msg_br_img));

  imageTransport(imgs, imgs_dev_, img_w_, img_h_);

  inference_input_.imgs_dev = imgs_dev_;

  std::vector<Box> ego_boxes;
  float inference_duration = 0.f;

  bevdet_->DoInfer(inference_input_, ego_boxes, inference_duration);

  autoware_perception_msgs::msg::DetectedObjects bevdet_objects;
  bevdet_objects.header.frame_id = "base_link";
  bevdet_objects.header.stamp = msg_f_img->header.stamp;

  box3DToDetectedObjects(ego_boxes, bevdet_objects, class_names_, score_threshold_, has_twist_);

  pub_boxes_->publish(bevdet_objects);

  if (debug_mode_) {
    publishDebugMarkers(pub_markers_, bevdet_objects);
  }
}

cv::Mat TRTBEVDetNode::cloneAndResize(const sensor_msgs::msg::Image::ConstSharedPtr & msg)
{
  cv::Mat img = cv_bridge::toCvShare(msg, "bgr8")->image.clone();
  if (img.size() != cv::Size(img_w_, img_h_)) {
    cv::resize(img, img, cv::Size(img_w_, img_h_));  // Resize if needed
  }
  return img;
}

void imageTransport(std::vector<cv::Mat> imgs, uchar * out_imgs, size_t width, size_t height)
{
  uchar * temp_gpu = nullptr;
  CHECK_CUDA(cudaMalloc(&temp_gpu, width * height * 3));

  for (size_t i = 0; i < imgs.size(); i++) {
    cv::cvtColor(imgs[i], imgs[i], cv::COLOR_BGR2RGB);
    CHECK_CUDA(cudaMemcpy(temp_gpu, imgs[i].data, width * height * 3, cudaMemcpyHostToDevice));
    convert_RGBHWC_to_BGRCHW(temp_gpu, out_imgs + i * width * height * 3, 3, height, width);
  }
  CHECK_CUDA(cudaFree(temp_gpu));
}

void convert_RGBHWC_to_BGRCHW(uchar *input, uchar *output, 
                                                        int channels, int height, int width);

#endif

int BEVDet::DoInfer(const camsData& cam_data, std::vector<Box> &out_detections, float &cost_time,
                                                                                    int idx){

    printf("-------------------%d-------------------\n", idx + 1);

    printf("scenes_token : %s, timestamp : %lld\n", cam_data.param.scene_token.data(),
                                cam_data.param.timestamp);

    auto start = high_resolution_clock::now();
    CHECK_CUDA(cudaMemcpy(trt_buffer_dev[buffer_map["images"]], cam_data.imgs_dev,
                trt_buffer_sizes[buffer_map["images"]], cudaMemcpyDeviceToDevice));

    InitCamParams(cam_data.param.cams2ego_rot,
                cam_data.param.cams2ego_trans,
                cam_data.param.cams_intrin);

    GetAdjBEVFeature(cam_data.param.scene_token,
                    cam_data.param.ego2global_rot,
                    cam_data.param.ego2global_trans);

    if(!trt_context->executeV2(trt_buffer_dev)){
        printf("BEVDet forward failing!\n");
    }

    adj_frame_ptr->saveFrameBuffer(trt_buffer_dev[buffer_map["curr_bevfeat"]],
                                    cam_data.param.scene_token,
                                    cam_data.param.ego2global_rot,
                                    cam_data.param.ego2global_trans);


    auto end = high_resolution_clock::now();

    postprocess_ptr->DoPostprocess(post_buffer, out_detections);

    CHECK_CUDA(cudaDeviceSynchronize());

    auto post_end = high_resolution_clock::now();

    duration<double> infer_t = post_end - start;
    duration<double> engine_t = end - start;
    duration<double> post_t = post_end - end;

    cost_time = infer_t.count() * 1000;
    printf("TRT-Engine  : %.5lf ms\n", engine_t.count() * 1000);
    printf("Postprocess : %.5lf ms\n", post_t.count() * 1000);
    printf("Inference   : %.5lf ms\n", infer_t.count() * 1000); 

    printf("Detected %ld objects\n", out_detections.size());

    return EXIT_SUCCESS;
}

void BEVDet::InitCamParams(const std::vector<Eigen::Quaternion<float>> &curr_cams2ego_rot,
                           const std::vector<Eigen::Translation3f> &curr_cams2ego_trans,
                           const std::vector<Eigen::Matrix3f> &curr_cams_intrin){
    for(int i = 0; i < N_img; i++){
        cam_params_host[i * cam_params_size +  0] = curr_cams_intrin[i](0, 0);
        cam_params_host[i * cam_params_size +  1] = curr_cams_intrin[i](1, 1);
        cam_params_host[i * cam_params_size +  2] = curr_cams_intrin[i](0, 2);
        cam_params_host[i * cam_params_size +  3] = curr_cams_intrin[i](1, 2);
        cam_params_host[i * cam_params_size +  4] = post_rot(0, 0);
        cam_params_host[i * cam_params_size +  5] = post_rot(0, 1);
        cam_params_host[i * cam_params_size +  6] = post_trans.translation()(0);
        cam_params_host[i * cam_params_size +  7] = post_rot(1, 0);
        cam_params_host[i * cam_params_size +  8] = post_rot(1, 1);
        cam_params_host[i * cam_params_size +  9] = post_trans.translation()(1);
        cam_params_host[i * cam_params_size + 10] = 1.f; // bda 0 0
        cam_params_host[i * cam_params_size + 11] = 0.f; // bda 0 1
        cam_params_host[i * cam_params_size + 12] = 0.f; // bda 1 0
        cam_params_host[i * cam_params_size + 13] = 1.f; // bda 1 1
        cam_params_host[i * cam_params_size + 14] = 1.f; // bda 2 2
        cam_params_host[i * cam_params_size + 15] = curr_cams2ego_rot[i].matrix()(0, 0);
        cam_params_host[i * cam_params_size + 16] = curr_cams2ego_rot[i].matrix()(0, 1);
        cam_params_host[i * cam_params_size + 17] = curr_cams2ego_rot[i].matrix()(0, 2);
        cam_params_host[i * cam_params_size + 18] = curr_cams2ego_trans[i].translation()(0);
        cam_params_host[i * cam_params_size + 19] = curr_cams2ego_rot[i].matrix()(1, 0);
        cam_params_host[i * cam_params_size + 20] = curr_cams2ego_rot[i].matrix()(1, 1);
        cam_params_host[i * cam_params_size + 21] = curr_cams2ego_rot[i].matrix()(1, 2);
        cam_params_host[i * cam_params_size + 22] = curr_cams2ego_trans[i].translation()(1);
        cam_params_host[i * cam_params_size + 23] = curr_cams2ego_rot[i].matrix()(2, 0);
        cam_params_host[i * cam_params_size + 24] = curr_cams2ego_rot[i].matrix()(2, 1);
        cam_params_host[i * cam_params_size + 25] = curr_cams2ego_rot[i].matrix()(2, 2);
        cam_params_host[i * cam_params_size + 26] = curr_cams2ego_trans[i].translation()(2);
    }


    CHECK_CUDA(cudaMemcpy(trt_buffer_dev[buffer_map["cam_params"]], cam_params_host,
                       trt_buffer_sizes[buffer_map["cam_params"]], cudaMemcpyHostToDevice));

    //printf("transs : %d cam : %d\n", transform_size, cam_params_size);
}

void BEVDet::GetAdjBEVFeature(const std::string &curr_scene_token,
                         const Eigen::Quaternion<float> &ego2global_rot,
                         const Eigen::Translation3f &ego2global_trans) {

    int flag = 1;
    if(adj_frame_ptr->lastScenesToken() != curr_scene_token){
        adj_frame_ptr->reset();
        flag = 0;
    }

    // idx越小, adj_bevfeat越新
    for(int i = 0; i < adj_num; i++){
        const void* adj_buffer = adj_frame_ptr->getFrameBuffer(i);

        size_t buf_size = trt_buffer_sizes[buffer_map["adj_feats"]] / adj_num;

        CHECK_CUDA(cudaMemcpy((char*)trt_buffer_dev[buffer_map["adj_feats"]] + i * buf_size,
                                adj_buffer, buf_size, cudaMemcpyDeviceToDevice));

        Eigen::Quaternion<float> adj_ego2global_rot;
        Eigen::Translation3f adj_ego2global_trans;
        adj_frame_ptr->getEgo2Global(i, adj_ego2global_rot, adj_ego2global_trans);

        GetCurr2AdjTransform(ego2global_rot,
                            adj_ego2global_rot,
                            ego2global_trans,
                            adj_ego2global_trans,
                            (float *)trt_buffer_dev[buffer_map["transforms"]] + i * transform_size);
    }
    CHECK_CUDA(cudaMemcpy(trt_buffer_dev[buffer_map["flag"]], &flag,
                        trt_buffer_sizes[buffer_map["flag"]], cudaMemcpyHostToDevice));

}

const std::string& lastScenesToken() const{
    return scenes_token[last];
}

void getEgo2Global(int idx, 
                Eigen::Quaternion<float> &adj_ego2global_rot, 
                Eigen::Translation3f &adj_ego2global_trans){
    idx = (-idx + last + n) % n;
    adj_ego2global_rot = ego2global_rot[idx];
    adj_ego2global_trans = ego2global_trans[idx];
}

void BEVDet::GetCurr2AdjTransform(const Eigen::Quaternion<float> &curr_ego2global_rot,
                                const Eigen::Quaternion<float> &adj_ego2global_rot,
                                const Eigen::Translation3f &curr_ego2global_trans,
                                const Eigen::Translation3f &adj_ego2global_trans,
                                float* transform_dev){
    Eigen::Matrix4f curr_e2g_transform;
    Eigen::Matrix4f adj_e2g_transform;

    for(int i = 0; i < 3; i++){
        for(int j = 0; j < 3; j++){
            curr_e2g_transform(i, j) = curr_ego2global_rot.matrix()(i, j);
            adj_e2g_transform(i, j) = adj_ego2global_rot.matrix()(i, j);
        }
    }
    for(int i = 0; i < 3; i++){
        curr_e2g_transform(i, 3) = curr_ego2global_trans.vector()(i);
        adj_e2g_transform(i, 3) = adj_ego2global_trans.vector()(i);

        curr_e2g_transform(3, i) = 0.f;
        adj_e2g_transform(3, i) = 0.f;
    }
    curr_e2g_transform(3, 3) = 1.f;
    adj_e2g_transform(3, 3) = 1.f;

    Eigen::Matrix4f currEgo2adjEgo = adj_e2g_transform.inverse() * curr_e2g_transform;
    Eigen::Matrix3f currEgo2adjEgo_2d;
    for(int i = 0; i < 2; i++){
        for(int j = 0; j < 2; j++){
            currEgo2adjEgo_2d(i, j) = currEgo2adjEgo(i, j);
        }
    }
    currEgo2adjEgo_2d(2, 0) = 0.f;
    currEgo2adjEgo_2d(2, 1) = 0.f;
    currEgo2adjEgo_2d(2, 2) = 1.f;
    currEgo2adjEgo_2d(0, 2) = currEgo2adjEgo(0, 3);
    currEgo2adjEgo_2d(1, 2) = currEgo2adjEgo(1, 3);

    Eigen::Matrix3f gridbev2egobev;
    gridbev2egobev(0, 0) = x_step;
    gridbev2egobev(1, 1) = y_step;
    gridbev2egobev(0, 2) = x_start;
    gridbev2egobev(1, 2) = y_start;
    gridbev2egobev(2, 2) = 1.f;

    gridbev2egobev(0, 1) = 0.f;
    gridbev2egobev(1, 0) = 0.f;
    gridbev2egobev(2, 0) = 0.f;
    gridbev2egobev(2, 1) = 0.f;

    Eigen::Matrix3f currgrid2adjgrid = gridbev2egobev.inverse() * currEgo2adjEgo_2d * gridbev2egobev;

    CHECK_CUDA(cudaMemcpy(transform_dev, Eigen::Matrix3f(currgrid2adjgrid.transpose()).data(),
                                   transform_size * sizeof(float), cudaMemcpyHostToDevice));
}

bool executeV2(void* const* bindings) noexcept
{
    return mImpl->executeV2(bindings);
}

void PostprocessGPU::DoPostprocess(void ** const bev_buffer, std::vector<Box>& out_detections){

    // bev_buffer : BEV_feat, reg_0, hei_0, dim_0, rot_0, vel_0, heatmap_0, reg_1 ...
    const int task_num = class_num_pre_task.size();
    int cur_start_label = 0;
    for(int i = 0; i < task_num; i++){
        float* reg = (float*)bev_buffer[i * 6 + 0];     // 2 x 128 x 128
        float* hei = (float*)bev_buffer[i * 6 + 1];     // 1 x 128 x 128
        float* dim = (float*)bev_buffer[i * 6 + 2];     // 3 x 128 x 128
        float* rot = (float*)bev_buffer[i * 6 + 3];     // 2 x 128 x 128
        float* vel = (float*)bev_buffer[i * 6 + 4];     // 2 x 128 x 128
        float* heatmap = (float*)bev_buffer[i * 6 + 5]; // c x 128 x 128

        dim3 grid(DIVUP(map_size, NUM_THREADS));
        CHECK_CUDA(cudaMemset(valid_box_num, 0, sizeof(int)));
        BEVDecodeObjectKernel<<<grid, NUM_THREADS>>>(map_size, score_thresh, 
                                         x_start, y_start, x_step, y_step, output_h,
                                         output_w, down_sample, class_num_pre_task[i],
                                         cur_start_label, reg, hei, dim, rot, 
                                         vel, 
                                         heatmap,
                                         boxes_dev, score_dev, cls_dev, valid_box_num,
                                         nms_rescale_factor_dev);

        /*
        此时 boxes_dev, score_dev, cls_dev 有 valid_box_num 个元素，可能大于nms_pre_maxnum, 而且是无序排列的
        */ 
        int box_num_pre = 0;
        CHECK_CUDA(cudaMemcpy(&box_num_pre, valid_box_num, sizeof(int), cudaMemcpyDeviceToHost));

        thrust::sequence(thrust::device, sorted_indices_dev, sorted_indices_dev + box_num_pre);
        thrust::sort_by_key(thrust::device, score_dev, score_dev + box_num_pre, 
                            sorted_indices_dev, thrust::greater<float>());
        // 此时 score_dev 是降序排列的，而 sorted_indices_dev 索引着原顺序，
        // 即 sorted_indices_dev[i] = j; i:现在的位置，j:原索引;  j:[0, map_size)


        box_num_pre = std::min(box_num_pre, nms_pre_maxnum);

        int box_num_post = iou3d_nms->DoIou3dNms(box_num_pre, boxes_dev, 
                                                        sorted_indices_dev, keep_data_host);

        box_num_post = std::min(box_num_post, nms_post_maxnum);


        CHECK_CUDA(cudaMemcpy(sorted_indices_host, sorted_indices_dev, box_num_pre * sizeof(int),
                                                                    cudaMemcpyDeviceToHost));
        CHECK_CUDA(cudaMemcpy(boxes_host, boxes_dev, kBoxBlockSize * map_size * sizeof(float),
                                                                    cudaMemcpyDeviceToHost));
        CHECK_CUDA(cudaMemcpy(score_host, score_dev, box_num_pre * sizeof(float), 
                                                                    cudaMemcpyDeviceToHost));
        CHECK_CUDA(cudaMemcpy(cls_host, cls_dev, map_size * sizeof(float), 
                                                                    cudaMemcpyDeviceToHost));


        for (auto j = 0; j < box_num_post; j++) {
            int k = keep_data_host[j];
            int idx = sorted_indices_host[k];
            Box box;
            box.x = boxes_host[idx * kBoxBlockSize + 0];
            box.y = boxes_host[idx * kBoxBlockSize + 1];
            box.z = boxes_host[idx * kBoxBlockSize + 2];
            box.l = boxes_host[idx * kBoxBlockSize + 3] / nms_rescale_factor[cls_host[idx]];
            box.w = boxes_host[idx * kBoxBlockSize + 4] / nms_rescale_factor[cls_host[idx]];
            box.h = boxes_host[idx * kBoxBlockSize + 5] / nms_rescale_factor[cls_host[idx]];
            box.r = boxes_host[idx * kBoxBlockSize + 6];
            box.vx = boxes_host[idx * kBoxBlockSize + 7];
            box.vy = boxes_host[idx * kBoxBlockSize + 8];

            box.label = cls_host[idx];
            box.score = score_host[k];
            box.z -= box.h * 0.5; // bottom height
            out_detections.push_back(box);
        }

        cur_start_label += class_num_pre_task[i];
    }
}

__global__ void BEVDecodeObjectKernel(const int map_size,         // 40000
                                   const float score_thresh,   // 0.1
                                //    const int nms_pre_max_size, // 4096
                                   const float x_start,
                                   const float y_start,
                                   const float x_step,
                                   const float y_step,
                                   const int output_h,
                                   const int output_w,
                                   const int downsample_size,
                                   const int num_class_in_task,
                                   const int cls_range,
                                   const float* reg,
                                   const float* hei,
                                   const float* dim,
                                   const float* rot,
                                   const float* vel,
                                   const float* cls,
                                   float* res_box,
                                   float* res_conf,
                                   int* res_cls,
                                   int* res_box_num,
                                   float* rescale_factor){  // 根据置信度，初筛，筛选后有res_box_num个box，不超过nms_pre_max_size 4096
    int idx = threadIdx.x + blockDim.x * blockIdx.x;
    if (idx >= map_size) return;

    float max_score = cls[idx]; // 初始化为task的第一个类
    int label = cls_range;      // 初始化为task的第一个类
    for (int i = 1; i < num_class_in_task; ++i) {
        float cur_score = cls[idx + i * map_size];
        if (cur_score > max_score){
            max_score = cur_score;
            label = i + cls_range;
        }
    }

    int coor_x = idx % output_h;  //
    int coor_y = idx / output_w;  //

    float conf = sigmoid_gpu(max_score); // 计算置信度
    if (conf > score_thresh){
        int cur_valid_box_id = atomicAdd(res_box_num, 1);
        res_box[cur_valid_box_id * kBoxBlockSize + 0] = 
            (reg[idx + 0 * map_size] + coor_x) * x_step + x_start;
        res_box[cur_valid_box_id * kBoxBlockSize + 1] = 
            (reg[idx + 1 * map_size] + coor_y) * y_step + y_start;
        res_box[cur_valid_box_id * kBoxBlockSize + 2] = hei[idx];
        res_box[cur_valid_box_id * kBoxBlockSize + 3] = 
                                expf(dim[idx + 0 * map_size]) * rescale_factor[label]; // nms scale
        res_box[cur_valid_box_id * kBoxBlockSize + 4] = 
                                expf(dim[idx + 1 * map_size]) * rescale_factor[label];
        res_box[cur_valid_box_id * kBoxBlockSize + 5] = 
                                expf(dim[idx + 2 * map_size]) * rescale_factor[label];
        res_box[cur_valid_box_id * kBoxBlockSize + 6] = atan2f(rot[idx], rot[idx + map_size]);
        res_box[cur_valid_box_id * kBoxBlockSize + 7] = vel[idx];
        res_box[cur_valid_box_id * kBoxBlockSize + 8] = vel[idx + map_size];


        res_conf[cur_valid_box_id] = conf;
        res_cls[cur_valid_box_id] = label;
    }
}

int Iou3dNmsCuda::DoIou3dNms(const int box_num_pre,
                             const float* res_box,
                             const int* res_sorted_indices,
                             long* host_keep_data) {
  const int col_blocks = DIVUP(box_num_pre, THREADS_PER_BLOCK_NMS);      // 划分多少块
  // printf("box_num_pre=%d, col_blocks=%d\n", box_num_pre, col_blocks);
  unsigned long long* dev_mask = NULL;
  cudaMalloc((void**)&dev_mask, box_num_pre * col_blocks * sizeof(unsigned long long));  // 
  // THREADS_PER_BLOCK_NMS 掩码的长度
  dim3 blocks(DIVUP(box_num_pre, THREADS_PER_BLOCK_NMS),
              DIVUP(box_num_pre, THREADS_PER_BLOCK_NMS));
  dim3 threads(THREADS_PER_BLOCK_NMS);
  RotatedNmsWithIndicesKernel<<<blocks, threads>>>(box_num_pre,
                                                   nms_overlap_thresh_,
                                                   res_box,
                                                   res_sorted_indices,
                                                   dev_mask);

  unsigned long long host_mask[box_num_pre * col_blocks];
  cudaMemcpy(host_mask, dev_mask, box_num_pre * col_blocks * sizeof(unsigned long long), cudaMemcpyDeviceToHost);
  cudaFree(dev_mask);

  unsigned long long host_remv[col_blocks];
  memset(host_remv, 0, col_blocks * sizeof(unsigned long long));
  int num_to_keep = 0;
  for (int i = 0; i < box_num_pre; i++) {
    int nblock = i / THREADS_PER_BLOCK_NMS;
    int inblock = i % THREADS_PER_BLOCK_NMS;
    if (!(host_remv[nblock] & (1ULL << inblock))) { // 满足此要求说明和前面选中的所有box都不冲突
      host_keep_data[num_to_keep++] = i;           // 把满足的box加入
      for (int j = nblock; j < col_blocks; j++) { // 把和序号i的box，overlap超过阈值的都考虑上
        host_remv[j] |= host_mask[i * col_blocks + j];
      }
    }
  }

  if (cudaSuccess != cudaGetLastError()) printf("Error!\n");
  return num_to_keep;
}

__global__ void RotatedNmsWithIndicesKernel(const int boxes_num,
                                            const float nms_overlap_thresh,
                                            const float* res_box,
                                            const int* res_sorted_indices,
                                            unsigned long long* mask) {
  const int row_start = blockIdx.y;
  const int col_start = blockIdx.x;

  const int row_size = fminf(boxes_num - row_start * THREADS_PER_BLOCK_NMS, THREADS_PER_BLOCK_NMS);
  const int col_size = fminf(boxes_num - col_start * THREADS_PER_BLOCK_NMS, THREADS_PER_BLOCK_NMS);

  __shared__ float block_boxes[THREADS_PER_BLOCK_NMS * kBoxBlockSize];

  if (threadIdx.x < col_size) { // 419, 420有两种情况，分情况讨论
    const int col_actual_idx = res_sorted_indices[THREADS_PER_BLOCK_NMS * col_start + threadIdx.x];
    block_boxes[threadIdx.x * kBoxBlockSize + 0] = res_box[col_actual_idx * kBoxBlockSize + 0];
    block_boxes[threadIdx.x * kBoxBlockSize + 1] = res_box[col_actual_idx * kBoxBlockSize + 1];
    block_boxes[threadIdx.x * kBoxBlockSize + 2] = res_box[col_actual_idx * kBoxBlockSize + 2];
    block_boxes[threadIdx.x * kBoxBlockSize + 3] = res_box[col_actual_idx * kBoxBlockSize + 3];
    block_boxes[threadIdx.x * kBoxBlockSize + 4] = res_box[col_actual_idx * kBoxBlockSize + 4];
    block_boxes[threadIdx.x * kBoxBlockSize + 5] = res_box[col_actual_idx * kBoxBlockSize + 5];
    block_boxes[threadIdx.x * kBoxBlockSize + 6] = res_box[col_actual_idx * kBoxBlockSize + 6];
  }
  __syncthreads(); // 等待块内的线程

  if (threadIdx.x < row_size) { //
    const int cur_box_idx = THREADS_PER_BLOCK_NMS * row_start + threadIdx.x;
    const int row_actual_idx = res_sorted_indices[cur_box_idx];

    float cur_box[kBoxBlockSize];
    cur_box[0] = res_box[row_actual_idx * kBoxBlockSize + 0];
    cur_box[1] = res_box[row_actual_idx * kBoxBlockSize + 1];
    cur_box[2] = res_box[row_actual_idx * kBoxBlockSize + 2];
    cur_box[3] = res_box[row_actual_idx * kBoxBlockSize + 3];
    cur_box[4] = res_box[row_actual_idx * kBoxBlockSize + 4];
    cur_box[5] = res_box[row_actual_idx * kBoxBlockSize + 5];
    cur_box[6] = res_box[row_actual_idx * kBoxBlockSize + 6];

    int i = 0;
    unsigned long long t = 0;
    int start = 0;
    if (row_start == col_start) {
      start = threadIdx.x + 1;  // 此时不和 [0 ~ threadIdx.x) 的比吗? FIXME
    }                           // 认为这里是正确的，都不需要和小于自己序号的比，如果col小于row,也不需要比
    for (i = start; i < col_size; i++) {
      if (iou_bev(cur_box, block_boxes + i * kBoxBlockSize) > nms_overlap_thresh) {
        t |= 1ULL << i;
      }
    }

    const int col_blocks = DIVUP(boxes_num, THREADS_PER_BLOCK_NMS);
    // assume cur_box_idx = 21, col_start = 0, row_start = 0 , threadIdx = 21,
    // mark 21 th box and top 64 boxes
    mask[cur_box_idx * col_blocks + col_start] = t;
    // 也可以 col_start * boxes_num + cur_box_idx 
  }
}

__device__ inline float iou_bev(const float* box_a, const float* box_b) {
  // params box_a: [x, y, z, dx, dy, dz, heading]
  // params box_b: [x, y, z, dx, dy, dz, heading]
  float sa = box_a[3] * box_a[4];
  float sb = box_b[3] * box_b[4];
  float s_overlap = box_overlap(box_a, box_b);
  return s_overlap / fmaxf(sa + sb - s_overlap, EPS);
}

__device__ inline float box_overlap(const float* box_a, const float* box_b) {
  // params box_a: [x, y, z, dx, dy, dz, heading]
  // params box_b: [x, y, z, dx, dy, dz, heading]

  float a_angle = box_a[6], b_angle = box_b[6];
  float a_dx_half = box_a[3] / 2, b_dx_half = box_b[3] / 2,
        a_dy_half = box_a[4] / 2, b_dy_half = box_b[4] / 2;
  float a_x1 = box_a[0] - a_dx_half, a_y1 = box_a[1] - a_dy_half;
  float a_x2 = box_a[0] + a_dx_half, a_y2 = box_a[1] + a_dy_half;
  float b_x1 = box_b[0] - b_dx_half, b_y1 = box_b[1] - b_dy_half;
  float b_x2 = box_b[0] + b_dx_half, b_y2 = box_b[1] + b_dy_half;

  Point center_a(box_a[0], box_a[1]);
  Point center_b(box_b[0], box_b[1]);

#ifdef DEBUG
  printf(
      "a: (%.3f, %.3f, %.3f, %.3f, %.3f), b: (%.3f, %.3f, %.3f, %.3f, %.3f)\n",
      a_x1, a_y1, a_x2, a_y2, a_angle, b_x1, b_y1, b_x2, b_y2, b_angle);
  printf("center a: (%.3f, %.3f), b: (%.3f, %.3f)\n", center_a.x, center_a.y,
         center_b.x, center_b.y);
#endif

  Point box_a_corners[5];
  box_a_corners[0].set(a_x1, a_y1);
  box_a_corners[1].set(a_x2, a_y1);
  box_a_corners[2].set(a_x2, a_y2);
  box_a_corners[3].set(a_x1, a_y2);

  Point box_b_corners[5];
  box_b_corners[0].set(b_x1, b_y1);
  box_b_corners[1].set(b_x2, b_y1);
  box_b_corners[2].set(b_x2, b_y2);
  box_b_corners[3].set(b_x1, b_y2);

  // get oriented corners
  float a_angle_cos = cos(a_angle), a_angle_sin = sin(a_angle);
  float b_angle_cos = cos(b_angle), b_angle_sin = sin(b_angle);

  for (int k = 0; k < 4; k++) {
#ifdef DEBUG
    printf("before corner %d: a(%.3f, %.3f), b(%.3f, %.3f) \n", k,
           box_a_corners[k].x, box_a_corners[k].y, box_b_corners[k].x,
           box_b_corners[k].y);
#endif
    rotate_around_center(center_a, a_angle_cos, a_angle_sin, box_a_corners[k]);
    rotate_around_center(center_b, b_angle_cos, b_angle_sin, box_b_corners[k]);
#ifdef DEBUG
    printf("corner %d: a(%.3f, %.3f), b(%.3f, %.3f) \n", k, box_a_corners[k].x,
           box_a_corners[k].y, box_b_corners[k].x, box_b_corners[k].y);
#endif
  }

  box_a_corners[4] = box_a_corners[0];
  box_b_corners[4] = box_b_corners[0];

  // get intersection of lines
  Point cross_points[16];
  Point poly_center;
  int cnt = 0, flag = 0;

  poly_center.set(0, 0);
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < 4; j++) {
      flag = intersection(box_a_corners[i + 1], box_a_corners[i],
                          box_b_corners[j + 1], box_b_corners[j],
                          cross_points[cnt]);
      if (flag) {
        poly_center = poly_center + cross_points[cnt];
        cnt++;
#ifdef DEBUG
        printf(
            "Cross points (%.3f, %.3f): a(%.3f, %.3f)->(%.3f, %.3f), b(%.3f, "
            "%.3f)->(%.3f, %.3f) \n",
            cross_points[cnt - 1].x, cross_points[cnt - 1].y,
            box_a_corners[i].x, box_a_corners[i].y, box_a_corners[i + 1].x,
            box_a_corners[i + 1].y, box_b_corners[i].x, box_b_corners[i].y,
            box_b_corners[i + 1].x, box_b_corners[i + 1].y);
#endif
      }
    }
  }

  // check corners
  for (int k = 0; k < 4; k++) {
    if (check_in_box2d(box_a, box_b_corners[k])) {
      poly_center = poly_center + box_b_corners[k];
      cross_points[cnt] = box_b_corners[k];
      cnt++;
#ifdef DEBUG
      printf("b corners in a: corner_b(%.3f, %.3f)", cross_points[cnt - 1].x,
             cross_points[cnt - 1].y);
#endif
    }
    if (check_in_box2d(box_b, box_a_corners[k])) {
      poly_center = poly_center + box_a_corners[k];
      cross_points[cnt] = box_a_corners[k];
      cnt++;
#ifdef DEBUG
      printf("a corners in b: corner_a(%.3f, %.3f)", cross_points[cnt - 1].x,
             cross_points[cnt - 1].y);
#endif
    }
  }

  poly_center.x /= cnt;
  poly_center.y /= cnt;

  // sort the points of polygon
  Point temp;
  for (int j = 0; j < cnt - 1; j++) {
    for (int i = 0; i < cnt - j - 1; i++) {
      if (point_cmp(cross_points[i], cross_points[i + 1], poly_center)) {
        temp = cross_points[i];
        cross_points[i] = cross_points[i + 1];
        cross_points[i + 1] = temp;
      }
    }
  }

#ifdef DEBUG
  printf("cnt=%d\n", cnt);
  for (int i = 0; i < cnt; i++) {
    printf("All cross point %d: (%.3f, %.3f)\n", i, cross_points[i].x,
           cross_points[i].y);
  }
#endif

  // get the overlap areas
  float area = 0;
  for (int k = 0; k < cnt - 1; k++) {
    area += cross(cross_points[k] - cross_points[0],
                  cross_points[k + 1] - cross_points[0]);
  }

  return fabs(area) / 2.0;
}

__device__ inline void rotate_around_center(const Point& center,
                                            const float angle_cos,
                                            const float angle_sin, 
                                            Point& p) {
  float new_x = (p.x - center.x) * angle_cos + (p.y - center.y) * (-angle_sin) + center.x;
  float new_y = (p.x - center.x) * angle_sin + (p.y - center.y) * angle_cos + center.y;
  p.set(new_x, new_y);
}

__device__ inline int intersection(const Point& p1, const Point& p0,
                                   const Point& q1, const Point& q0,
                                   Point& ans) {
  // fast exclusion
  if (check_rect_cross(p0, p1, q0, q1) == 0) return 0;

  // check cross standing
  float s1 = cross(q0, p1, p0);
  float s2 = cross(p1, q1, p0);
  float s3 = cross(p0, q1, q0);
  float s4 = cross(q1, p1, q0);

  if (!(s1 * s2 > 0 && s3 * s4 > 0)) return 0;

  // calculate intersection of two lines
  float s5 = cross(q1, p1, p0);
  if (fabs(s5 - s1) > EPS) {
    ans.x = (s5 * q0.x - s1 * q1.x) / (s5 - s1);
    ans.y = (s5 * q0.y - s1 * q1.y) / (s5 - s1);

  } else {
    float a0 = p0.y - p1.y, b0 = p1.x - p0.x, c0 = p0.x * p1.y - p1.x * p0.y;
    float a1 = q0.y - q1.y, b1 = q1.x - q0.x, c1 = q0.x * q1.y - q1.x * q0.y;
    float D = a0 * b1 - a1 * b0;

    ans.x = (b0 * c1 - b1 * c0) / D;
    ans.y = (a1 * c0 - a0 * c1) / D;
  }

  return 1;
}

__device__ int check_rect_cross(const Point& p1, const Point& p2,
                                const Point& q1, const Point& q2) {
  int ret = min(p1.x, p2.x) <= max(q1.x, q2.x) &&
            min(q1.x, q2.x) <= max(p1.x, p2.x) &&
            min(p1.y, p2.y) <= max(q1.y, q2.y) &&
            min(q1.y, q2.y) <= max(p1.y, p2.y);
  return ret;
}

__device__ inline float cross(const Point& a, const Point& b) {
  return a.x * b.y - a.y * b.x;
}

__device__ inline int check_in_box2d(const float* box, const Point& p) {
  // params: (7) [x, y, z, dx, dy, dz, heading]
  const float kMargin = 1e-2;

  float center_x = box[0], center_y = box[1];
  // rotate the point in the opposite direction of box
  float angle_cos = cos(-box[6]);
  float angle_sin = sin(-box[6]);
  float rot_x = (p.x - center_x) * angle_cos + (p.y - center_y) * (-angle_sin);
  float rot_y = (p.x - center_x) * angle_sin + (p.y - center_y) * angle_cos;

  return (fabs(rot_x) < box[3] / 2 + kMargin &&
          fabs(rot_y) < box[4] / 2 + kMargin);
}

__device__ inline int point_cmp(const Point& a, const Point& b,
                                const Point& center) {
  return atan2(a.y - center.y, a.x - center.x) >
         atan2(b.y - center.y, b.x - center.x);
}

__device__ inline float cross(const Point& a, const Point& b) {
  return a.x * b.y - a.y * b.x;
}

void box3DToDetectedObjects(
  const std::vector<Box> & boxes, autoware_perception_msgs::msg::DetectedObjects & bevdet_objects,
  const std::vector<std::string> & class_names, const float & score_threshold,
  const bool has_twist = true)
{
  for (const auto & b : boxes) {
    if (b.score < score_threshold) continue;
    autoware_perception_msgs::msg::DetectedObject obj;

    obj.existence_probability = b.score;
    // classification
    autoware_perception_msgs::msg::ObjectClassification classification;
    classification.probability = 1.0f;
    if (b.label >= 0 && static_cast<size_t>(b.label) < class_names.size()) {
      classification.label = getSemanticType(class_names[b.label]);
    } else {
      classification.label = Label::UNKNOWN;
    }
    obj.classification.emplace_back(classification);

    // pose and shape
    // set box center (x, y, z + h/2) to object's position
    geometry_msgs::msg::Point p;
    p.x = b.x;
    p.y = b.y;
    p.z = b.z + b.h / 2.0;
    obj.kinematics.pose_with_covariance.pose.position = p;

    tf2::Quaternion q;
    q.setRPY(0, 0, b.r);
    obj.kinematics.pose_with_covariance.pose.orientation = tf2::toMsg(q);

    obj.shape.type = autoware_perception_msgs::msg::Shape::BOUNDING_BOX;

    geometry_msgs::msg::Vector3 v;
    v.x = b.l;
    v.y = b.w;
    v.z = b.h;
    obj.shape.dimensions = v;
    if (has_twist) {
      float vel_x = b.vx;
      float vel_y = b.vy;
      geometry_msgs::msg::Twist twist;
      twist.linear.x = std::sqrt(std::pow(vel_x, 2) + std::pow(vel_y, 2));
      twist.angular.z = 2 * (std::atan2(vel_y, vel_x) - b.r);
      obj.kinematics.twist_with_covariance.twist = twist;
      obj.kinematics.has_twist = has_twist;
    }

    bevdet_objects.objects.emplace_back(obj);
  }
}

uint8_t getSemanticType(const std::string & class_name)
{
  if (class_name == "car") {
    return Label::CAR;
  } else if (class_name == "truck") {
    return Label::TRUCK;
  } else if (class_name == "bus") {
    return Label::BUS;
  } else if (class_name == "trailer") {
    return Label::TRAILER;
  } else if (class_name == "bicycle") {
    return Label::BICYCLE;
  } else if (class_name == "motorcycle") {
    return Label::MOTORCYCLE;
  } else if (class_name == "pedestrian") {
    return Label::PEDESTRIAN;
  } else {
    return Label::UNKNOWN;
  }
}
